import React,{useEffect,useMemo,useState}from'react';
import{BarChart3,ChefHat,ClipboardList,Factory,PackagePlus,RefreshCw,Search,ShieldAlert,ShoppingCart,Store,Trash2,Truck,WalletCards,X}from'lucide-react';
import{api,hasWorkforcePermission,type AccessLevel,type WorkforceContext}from'./auth';
import'./bakery.css';
import'./bakery-accountability.css';
import'./bakery-reports.css';
import'./bakery-controls.css';
import'./bakery-intelligence.css';
import{BakeryKpiStrip}from'./bakery-kpi-strip';
